/**
 * 結構為 資料欄位名，資料欄位描述，類型，是否允許為空 4項都是必需的
 */
function SchemaColumn(name, desc, dataType, allowNulls) {
	this.name = name;
	this.desc = desc;
	this.dataType = dataType;
	this.allowNulls = allowNulls;
}
/***
 * 根据配置的名称获取缓存对象
 * @param name
 * @returns
 */
function getSchemaColumn(name) {
	return jQuery.data($schemaBody,name);
}


